function (settings, time, ctx) {
  // ---------- SETTINGS ----------
  var VERTICAL      = false;                   // structural: false = horizontal bar (480x140: caption, scale, track, value), true = vertical bar (260x480)
  var MULTIPLIER    = settings.multiplier.value;      // value * multiplier (1 = escRPM as is; gear ratio, pole correction)
  var DIGITS        = settings.digits.value;          // decimal places of the value
  var AUTO_MAX      = settings.auto_max.value;        // scale maximum from the whole flight (rounded up to whole steps); off = Max RPM
  var MAX_RPM       = settings.max_rpm.value;         // scale maximum when Auto max is off (or no data yet)
  var SMOOTH_MS     = settings.smooth_ms.value;       // moving average window for the value in ms (0 = off)
  var PEAK_HOLD     = settings.peak_hold.value;       // show the momentary maximum with a fainter marker + ghost fill
  var HOLD_MS       = settings.hold_ms.value;         // how long the peak marker stays at the maximum before it starts sliding (ms)
  var SLIDE_SPEED   = settings.slide_speed.value;     // constant slide speed towards the current value, in % of the scale per second (100 = whole scale in 1 s)
  var PEAK_COLOR    = settings.peak_color.value;      // peak marker color
  var PEAK_OPACITY  = settings.peak_opacity.value;    // peak marker / ghost fill opacity 0..1 (fades out as it reaches the value)
  var MAJOR         = settings.major_tick.value;      // RPM between scale numbers (0 = auto; raised automatically so there are at most 20 numbers)
  var MINOR         = settings.minor_ticks.value;     // small ticks per number step (1 = one tick halfway, 0 = none)
  var DIVISOR       = settings.dial_divisor.value;    // scale numbers = RPM / divisor: 1 | 100 | 1000
  var SHOW_NUMBERS  = settings.show_numbers.value;    // show the scale numbers and ticks along the track
  var LABEL         = settings.label.value;           // caption in the top-left corner ('' = none)
  var UNIT          = settings.unit.value;            // unit text after the value ('' = none)
  var TRACK_COLOR   = settings.track_color.value;     // background track color
  var FILL_COLOR    = settings.fill_color.value;      // filled part color (0 .. current value)
  var MARKER_COLOR  = settings.marker_color.value;    // marker line at the end of the filled part
  var MARKER_OVER   = settings.marker_overhang.value; // how far the marker line sticks out past the track on each side, at the default size; scales with the widget
  var TEXT_COLOR    = settings.text_color.value;      // value / unit / caption color
  var TEXT_SHADOW   = settings.text_shadow.value;     // CSS text shadow behind all texts ('' = none)
  var NUM_COLOR     = settings.number_color.value;    // scale numbers and small ticks
  var FONT          = settings.font.value;            // font family
  var VALUE_SIZE    = settings.value_size.value;      // value font size at the default size; scales with the widget
  var LABEL_SIZE    = settings.label_size.value;      // caption font size at the default size; scales with the widget
  var NUM_SIZE      = settings.number_size.value;     // scale number font size at the default size; scales with the widget
  var TRACK_WIDTH   = settings.track_width.value;     // track thickness at the default size; scales with the widget
  var OPACITY       = settings.opacity.value;         // whole-widget opacity 0..1 (1 = opaque)
  var MAX_LABELS = 20;                                // hard cap on the number of scale numbers
  // -------------------------------
  var W = ctx.width, H = ctx.height;
  var DEFW = VERTICAL ? 260 : 480, DEFH = VERTICAL ? 480 : 140;
  var scale = Math.min(W / DEFW, H / DEFH);
  var col = ctx.columns[0];
  var s = ctx.state, i;

  // ---- current value (optionally smoothed) ----
  var cur = ctx.values[0];
  if (SMOOTH_MS > 0 && col && typeof cur === 'number') {   // outside the flight ctx.range still returns the edge sample: keep "--"
    var sam = ctx.range(col, time - SMOOTH_MS / 2, time + SMOOTH_MS / 2, 200) || [], sum = 0, cnt = 0;
    for (i = 0; i < sam.length; i++) if (typeof sam[i].v === 'number') { sum += sam[i].v; cnt++; }
    if (cnt) cur = sum / cnt;
  }
  if (typeof cur === 'number') cur = cur * MULTIPLIER; else cur = undefined;

  // ---- scale maximum + number step (cached per flight) ----
  function niceStep(range, minStep, maxCount) {            // smallest nice step (1, 2, 2.5, 5 x 10^n) >= minStep with <= maxCount steps
    var mags = [1, 2, 2.5, 5], mag = 1, k;
    while (mag * 1e6 < minStep) mag *= 10;
    for (k = 0; k < 400; k++) {
      var step = mags[k % 4] * mag;
      if (step >= minStep && range / step <= maxCount) return step;
      if (k % 4 === 3) mag *= 10;
    }
    return range;
  }
  var key = col + '|' + MULTIPLIER + '|' + AUTO_MAX + '|' + MAX_RPM + '|' + MAJOR + '|' + ctx.dataVersion;
  if (s.key !== key) {
    var mx = MAX_RPM > 0 ? MAX_RPM : 10000, auto = false;
    if (AUTO_MAX && col) {
      var st = ctx.stats(col);
      if (st && typeof st.max === 'number' && st.max * MULTIPLIER > 0) { mx = st.max * MULTIPLIER; auto = true; }
    }
    var mj = MAJOR > 0 ? niceStep(mx, MAJOR, MAX_LABELS) : niceStep(mx, 0, VERTICAL ? 8 : 6);
    if (auto) mx = Math.max(mj, Math.ceil(mx / mj - 1e-9) * mj);   // whole number of steps
    s.max = mx; s.major = mj; s.key = key; s.staticKey = null;
  }
  var MAX = s.max, major = s.major;

  // ---- momentary maximum (classic peak hold): rides on the value, holds HOLD_MS after the last real rise,
  //      then slides at a constant speed until it meets the value again; replayed from the smoothed history ----
  var peak = cur, alpha = 0;
  if (PEAK_HOLD && typeof cur === 'number' && col) {
    var speed = Math.max(1e-6, SLIDE_SPEED / 100 * MAX / 1000);          // units per ms
    var span = HOLD_MS + MAX / speed;
    var half = SMOOTH_MS > 0 ? SMOOTH_MS / 2 : 0;
    var raw = ctx.range(col, time - span - half, time + half, 2000) || [];
    var ser = raw, j;
    if (half > 0) {
      ser = []; var lo = 0, hi = 0, ssum = 0, scnt = 0;
      for (j = 0; j < raw.length; j++) {
        var tj = raw[j].t;
        while (hi < raw.length && raw[hi].t <= tj + half) { if (typeof raw[hi].v === 'number') { ssum += raw[hi].v; scnt++; } hi++; }
        while (lo < raw.length && raw[lo].t < tj - half) { if (typeof raw[lo].v === 'number') { ssum -= raw[lo].v; scnt--; } lo++; }
        ser.push({ t: tj, v: scnt > 0 ? ssum / scnt : raw[j].v });
      }
    }
    var eps = MAX * 0.01, pk = null, trough = 0, lastT = 0, lastRise = -1e12;
    for (i = 0; i < ser.length; i++) {
      var v = ser[i].v, t = ser[i].t;
      if (typeof v !== 'number' || t > time) continue;
      v = v * MULTIPLIER;
      if (pk === null) { pk = v; trough = v; lastT = t; continue; }
      if (t - lastRise > HOLD_MS) pk -= speed * (t - Math.max(lastT, lastRise + HOLD_MS));
      if (v >= pk) { pk = v; if (v < trough) trough = v; if (v - trough >= eps) lastRise = t; }
      else trough = v;
      lastT = t;
    }
    if (pk !== null) {
      if (time - lastRise > HOLD_MS) pk -= speed * (time - Math.max(lastT, lastRise + HOLD_MS));
      peak = Math.min(MAX, Math.max(cur, pk));
    }
    alpha = PEAK_OPACITY * Math.min(1, (peak - cur) / (MAX * 0.02));
    if (alpha < 0.02) alpha = 0;
  }

  // ---- geometry ----
  var p = 8 * scale, tw = TRACK_WIDTH * scale, fw = tw + 1.5 * scale, ovh = MARKER_OVER * scale;
  var fs = VALUE_SIZE * scale, lfs = LABEL_SIZE * scale, nfs = NUM_SIZE * scale, mw = tw * 0.38;
  var labelH = LABEL ? lfs * 1.5 : 0;
  var ov = 1.5 * scale;                                     // overlap so abutting shapes leave no seam
  var reach = Math.max(tw / 2 + ovh + mw / 2, fs * 0.55);   // half extent of marker / value text across the track
  // track axis: horizontal at y = ta from x = a0 (0) to a1 (max); vertical at x = ta from y = a0 (0, bottom) to a1 (max, top)
  var ta, a0, a1;
  if (VERTICAL) {
    ta = p + (SHOW_NUMBERS ? nfs * 2.4 : 0) + tw / 2 + ovh + mw / 2;
    a0 = H - p - tw / 2;
    a1 = labelH + p + Math.max(tw / 2, reach);
  } else {                                                  // rows: caption, scale numbers, track, value under the marker
    ta = labelH + p + (SHOW_NUMBERS ? nfs * 1.2 : 0) + tw / 2 + ovh + mw / 2 + 2 * scale;
    a0 = p + tw / 2;
    a1 = W - p - tw / 2;
  }
  function pos(v) { return a0 + Math.max(0, Math.min(1, v / MAX)) * (a1 - a0); }
  function num(v) { var d = v / DIVISOR; return (Math.abs(d - Math.round(d)) < 1e-6) ? String(Math.round(d)) : d.toFixed(1); }
  function seg(c1, c2, color, width, cap, extra) {          // straight track segment between axis coordinates c1..c2
    if (Math.abs(c2 - c1) < 0.01) return '';
    var x1 = VERTICAL ? ta : c1, y1 = VERTICAL ? c1 : ta, x2 = VERTICAL ? ta : c2, y2 = VERTICAL ? c2 : ta;
    return '<line x1="' + x1.toFixed(2) + '" y1="' + y1.toFixed(2) + '" x2="' + x2.toFixed(2) + '" y2="' + y2.toFixed(2) + '" stroke="' + color + '" stroke-width="' + width.toFixed(2) + '" stroke-linecap="' + cap + '"' + (extra || '') + '/>';
  }
  function marker(c, color, extra) {                         // line across the track, symmetric, sticking out ovh on both sides
    var e = tw / 2 + ovh;
    var x1 = VERTICAL ? ta - e : c, y1 = VERTICAL ? c : ta - e, x2 = VERTICAL ? ta + e : c, y2 = VERTICAL ? c : ta + e;
    return '<line x1="' + x1.toFixed(2) + '" y1="' + y1.toFixed(2) + '" x2="' + x2.toFixed(2) + '" y2="' + y2.toFixed(2) + '" stroke="' + color + '" stroke-width="' + mw.toFixed(2) + '" stroke-linecap="round"' + (extra || '') + '/>';
  }
  var shadow = TEXT_SHADOW ? 'text-shadow:' + TEXT_SHADOW : '';
  var dir = VERTICAL ? -1 : 1;                              // axis direction of growing values in screen coordinates

  // ---- static part: track, numbers, ticks, caption (built once per size / look) ----
  var staticKey = W + 'x' + H + '|' + MAX + '|' + major + '|' + MINOR + '|' + DIVISOR + '|' + SHOW_NUMBERS + '|' + LABEL + '|' + TRACK_COLOR + '|' + NUM_COLOR + '|' + TEXT_COLOR + '|' + TEXT_SHADOW + '|' + FONT + '|' + lfs + '|' + nfs + '|' + tw + '|' + ovh;
  if (s.staticKey !== staticKey) {
    var st2 = seg(a0, a1, TRACK_COLOR, tw, 'round');
    if (SHOW_NUMBERS) {
      var minor = MINOR >= 0 ? Math.round(MINOR) + 1 : 1;
      var tick = major / minor, total = Math.floor(MAX / tick + 1e-9);
      if (total > 200) { minor = 1; tick = major; total = Math.floor(MAX / tick + 1e-9); }
      var off = tw / 2 + ovh + mw / 2;                     // numbers sit outside the marker's reach
      for (i = 0; i <= total; i++) {
        var c = pos(i * tick), isNum = (i % minor === 0);
        if (VERTICAL) {
          if (isNum) st2 += '<text x="' + (ta - off - nfs * 0.3).toFixed(2) + '" y="' + c.toFixed(2) + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="end" dominant-baseline="central" style="' + shadow + '">' + num(i * tick) + '</text>';
          else st2 += '<line x1="' + (ta - off - nfs * 0.2).toFixed(2) + '" y1="' + c.toFixed(2) + '" x2="' + (ta - off - nfs * 0.8).toFixed(2) + '" y2="' + c.toFixed(2) + '" stroke="' + NUM_COLOR + '" stroke-width="' + (1.5 * scale).toFixed(2) + '" stroke-linecap="round"/>';
        } else {
          if (isNum) st2 += '<text x="' + c.toFixed(2) + '" y="' + (ta - off - nfs * 0.65).toFixed(2) + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central" style="' + shadow + '">' + num(i * tick) + '</text>';
          else st2 += '<line x1="' + c.toFixed(2) + '" y1="' + (ta - off - nfs * 0.25).toFixed(2) + '" x2="' + c.toFixed(2) + '" y2="' + (ta - off - nfs * 0.85).toFixed(2) + '" stroke="' + NUM_COLOR + '" stroke-width="' + (1.5 * scale).toFixed(2) + '" stroke-linecap="round"/>';
        }
      }
    }
    if (LABEL) st2 += '<text x="' + p.toFixed(2) + '" y="' + (p + lfs * 0.55).toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".85" font-size="' + lfs.toFixed(1) + '" font-weight="bold" letter-spacing="' + (1.5 * scale).toFixed(1) + '" dominant-baseline="central" style="' + shadow + '">' + LABEL + '</text>';
    s.staticSvg = st2; s.staticKey = staticKey;
  }

  // ---- dynamic part ----
  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="font-family:' + FONT + ';opacity:' + OPACITY + '">' + s.staticSvg;
  if (typeof cur === 'number') {
    var cc = pos(cur);
    if (alpha > 0) {
      var cp = pos(peak);
      out += seg(cc - dir * ov, cp, FILL_COLOR, fw, 'butt', ' stroke-opacity="' + (alpha * 0.5).toFixed(2) + '"');
      out += marker(cp, PEAK_COLOR, ' stroke-opacity="' + alpha.toFixed(2) + '"');
    }
    // rounded zero end as a half disc bulging backwards only, then a butt-ended fill up to the marker
    var hr = fw / 2, hx = VERTICAL ? ta : a0, hy = VERTICAL ? a0 : ta;
    out += VERTICAL
      ? '<path d="M' + (hx - hr).toFixed(2) + ',' + hy.toFixed(2) + ' A' + hr.toFixed(2) + ',' + hr.toFixed(2) + ' 0 0 0 ' + (hx + hr).toFixed(2) + ',' + hy.toFixed(2) + ' Z" fill="' + FILL_COLOR + '"/>'
      : '<path d="M' + hx.toFixed(2) + ',' + (hy - hr).toFixed(2) + ' A' + hr.toFixed(2) + ',' + hr.toFixed(2) + ' 0 0 0 ' + hx.toFixed(2) + ',' + (hy + hr).toFixed(2) + ' Z" fill="' + FILL_COLOR + '"/>';
    if (Math.abs(cc - a0) >= 0.01) out += seg(a0 - dir * ov, cc, FILL_COLOR, fw, 'butt');
    out += marker(cc, MARKER_COLOR);
    // value text: vertical bar — right of the marker; horizontal bar — centred under the marker, stopped at the box edges
    var txt = cur.toFixed(DIGITS), gap = tw / 2 + ovh + mw / 2 + fs * 0.2;
    var est = txt.length * fs * 0.58 + (UNIT ? fs * 0.4 * UNIT.length * 0.6 + fs * 0.15 : 0);
    var tx, ty, anchor = 'start';
    if (VERTICAL) { tx = ta + gap; ty = Math.max(a1, Math.min(a0, cc)); }
    else { anchor = 'middle'; ty = ta + tw / 2 + ovh + mw / 2 + fs * 0.6; tx = Math.max(p + est / 2, Math.min(W - p - est / 2, cc)); }
    out += '<text x="' + tx.toFixed(2) + '" y="' + ty.toFixed(2) + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" text-anchor="' + anchor + '" dominant-baseline="central" style="' + shadow + '">' + txt
      + (UNIT ? '<tspan font-size="' + (fs * 0.4).toFixed(1) + '" font-weight="normal" dx="' + (fs * 0.12).toFixed(1) + '">' + UNIT + '</tspan>' : '') + '</text>';
  } else {
    var nx = VERTICAL ? ta + tw / 2 + ovh + mw / 2 + fs * 0.2 : a0;
    out += '<text x="' + nx.toFixed(2) + '" y="' + (VERTICAL ? a0 : ta + tw / 2 + ovh + mw / 2 + fs * 0.6).toFixed(2) + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" dominant-baseline="central" style="' + shadow + '">--</text>';
  }
  out += '</svg>';
  return out;
}

