  }
  var MAX = s.max, major = s.major;

  // ---- momentary maximum (classic peak hold): rides on the value, holds HOLD_MS after the last real rise,
  //      then slides at a constant speed until it meets the value again; replayed from the smoothed history ----
  var peak = cur, alpha = 0;
  if (PEAK_HOLD && typeof cur === 'number' && col) {
    var speed = Math.max(1e-6, SLIDE_SPEED / 100 * MAX / 1000);          // units per ms
    var span = HOLD_MS + MAX / speed;
    var half = SMOOTH_MS > 0 ? SMOOTH_MS / 2 : 0;
    var raw = ctx.range(col, time - span - half, time + half, 2000) || [];
    var ser = raw, j;
    if (half > 0) {
      ser = []; var lo = 0, hi = 0, ssum = 0, scnt = 0;
      for (j = 0; j < raw.length; j++) {
        var tj = raw[j].t;
        while (hi < raw.length && raw[hi].t <= tj + half) { if (typeof raw[hi].v === 'number') { ssum += raw[hi].v; scnt++; } hi++; }
        while (lo < raw.length && raw[lo].t < tj - half) { if (typeof raw[lo].v === 'number') { ssum -= raw[lo].v; scnt--; } lo++; }
        ser.push({ t: tj, v: scnt > 0 ? ssum / scnt : raw[j].v });
      }
    }
    var eps = MAX * 0.01, pk = null, trough = 0, lastT = 0, lastRise = -1e12;
    for (i = 0; i < ser.length; i++) {
      var v = ser[i].v, t = ser[i].t;
      if (typeof v !== 'number' || t > time) continue;
      v = v * MULTIPLIER;
      if (pk === null) { pk = v; trough = v; lastT = t; continue; }
      if (t - lastRise > HOLD_MS) pk -= speed * (t - Math.max(lastT, lastRise + HOLD_MS));
      if (v >= pk) { pk = v; if (v < trough) trough = v; if (v - trough >= eps) lastRise = t; }
      else trough = v;
      lastT = t;
    }
    if (pk !== null) {
      if (time - lastRise > HOLD_MS) pk -= speed * (time - Math.max(lastT, lastRise + HOLD_MS));
      peak = Math.min(MAX, Math.max(cur, pk));
    }
    alpha = PEAK_OPACITY * Math.min(1, (peak - cur) / (MAX * 0.02));
    if (alpha < 0.02) alpha = 0;
  }

  // ---- geometry ----
  var p = 8 * scale, tw = TRACK_WIDTH * scale, fw = tw + 1.5 * scale, ovh = MARKER_OVER * scale;
  var fs = VALUE_SIZE * scale, lfs = LABEL_SIZE * scale, nfs = NUM_SIZE * scale, mw = tw * 0.38;
  var labelH = LABEL ? lfs * 1.5 : 0;
  var ov = 1.5 * scale;                                     // overlap so abutting shapes leave no seam
  var reach = Math.max(tw / 2 + ovh + mw / 2, fs * 0.55);   // half extent of marker / value text across the track
  // track axis: horizontal at y = ta from x = a0 (0) to a1 (max); vertical at x = ta from y = a0 (0, bottom) to a1 (max, top)
  var ta, a0, a1;
  if (VERTICAL) {
    ta = p + (SHOW_NUMBERS ? nfs * 2.4 : 0) + tw / 2 + ovh + mw / 2;
    a0 = H - p - tw / 2;
    a1 = labelH + p + Math.max(tw / 2, reach);
  } else {                                                  // rows: caption, scale numbers, track, value under the marker
    ta = labelH + p + (SHOW_NUMBERS ? nfs * 1.2 : 0) + tw / 2 + ovh + mw / 2 + 2 * scale;
    a0 = p + tw / 2;
    a1 = W - p - tw / 2;
  }
  function pos(v) { return a0 + Math.max(0, Math.min(1, v / MAX)) * (a1 - a0); }
  function num(v) { var d = v / DIVISOR; return (Math.abs(d - Math.round(d)) < 1e-6) ? String(Math.round(d)) : d.toFixed(1); }
  function seg(c1, c2, color, width, cap, extra) {          // straight track segment between axis coordinates c1..c2
    if (Math.abs(c2 - c1) < 0.01) return '';
    var x1 = VERTICAL ? ta : c1, y1 = VERTICAL ? c1 : ta, x2 = VERTICAL ? ta : c2, y2 = VERTICAL ? c2 : ta;
    return '<line x1="' + x1.toFixed(2) + '" y1="' + y1.toFixed(2) + '" x2="' + x2.toFixed(2) + '" y2="' + y2.toFixed(2) + '" stroke="' + color + '" stroke-width="' + width.toFixed(2) + '" stroke-linecap="' + cap + '"' + (extra || '') + '/>';
  }
  function marker(c, color, extra) {                         // line across the track, symmetric, sticking out ovh on both sides
    var e = tw / 2 + ovh;
    var x1 = VERTICAL ? ta - e : c, y1 = VERTICAL ? c : ta - e, x2 = VERTICAL ? ta + e : c, y2 = VERTICAL ? c : ta + e;
    return '<line x1="' + x1.toFixed(2) + '" y1="' + y1.toFixed(2) + '" x2="' + x2.toFixed(2) + '" y2="' + y2.toFixed(2) + '" stroke="' + color + '" stroke-width="' + mw.toFixed(2) + '" stroke-linecap="round"' + (extra || '') + '/>';
  }
  var shadow = TEXT_SHADOW ? 'text-shadow:' + TEXT_SHADOW : '';
  var dir = VERTICAL ? -1 : 1;                              // axis direction of growing values in screen coordinates

  // ---- static part: track, numbers, ticks, caption (built once per size / look) ----
  var staticKey = W + 'x' + H + '|' + MAX + '|' + major + '|' + MINOR + '|' + DIVISOR + '|' + SHOW_NUMBERS + '|' + LABEL + '|' + TRACK_COLOR + '|' + NUM_COLOR + '|' + TEXT_COLOR + '|' + TEXT_SHADOW + '|' + FONT + '|' + lfs + '|' + nfs + '|' + tw + '|' + ovh;
  if (s.staticKey !== staticKey) {
    var st2 = seg(a0, a1, TRACK_COLOR, tw, 'round');
    if (SHOW_NUMBERS) {
      var minor = MINOR >= 0 ? Math.round(MINOR) + 1 : 1;
      var tick = major / minor, total = Math.floor(MAX / tick + 1e-9);
      if (total > 200) { minor = 1; tick = major; total = Math.floor(MAX / tick + 1e-9); }
      var off = tw / 2 + ovh + mw / 2;                     // numbers sit outside the marker's reach
      for (i = 0; i <= total; i++) {
        var c = pos(i * tick), isNum = (i % minor === 0);
        if (VERTICAL) {
          if (isNum) st2 += '<text x="' + (ta - off - nfs * 0.3).toFixed(2) + '" y="' + c.toFixed(2) + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="end" dominant-baseline="central" style="' + shadow + '">' + num(i * tick) + '</text>';
          else st2 += '<line x1="' + (ta - off - nfs * 0.2).toFixed(2) + '" y1="' + c.toFixed(2) + '" x2="' + (ta - off - nfs * 0.8).toFixed(2) + '" y2="' + c.toFixed(2) + '" stroke="' + NUM_COLOR + '" stroke-width="' + (1.5 * scale).toFixed(2) + '" stroke-linecap="round"/>';
        } else {
          if (isNum) st2 += '<text x="' + c.toFixed(2) + '" y="' + (ta - off - nfs * 0.65).toFixed(2) + '" fill="' + NUM_COLOR + '" font-size="' + nfs.toFixed(1) + '" text-anchor="middle" dominant-baseline="central" style="' + shadow + '">' + num(i * tick) + '</text>';
          else st2 += '<line x1="' + c.toFixed(2) + '" y1="' + (ta - off - nfs * 0.25).toFixed(2) + '" x2="' + c.toFixed(2) + '" y2="' + (ta - off - nfs * 0.85).toFixed(2) + '" stroke="' + NUM_COLOR + '" stroke-width="' + (1.5 * scale).toFixed(2) + '" stroke-linecap="round"/>';
        }
      }
    }
    if (LABEL) st2 += '<text x="' + p.toFixed(2) + '" y="' + (p + lfs * 0.55).toFixed(2) + '" fill="' + TEXT_COLOR + '" fill-opacity=".85" font-size="' + lfs.toFixed(1) + '" font-weight="bold" letter-spacing="' + (1.5 * scale).toFixed(1) + '" dominant-baseline="central" style="' + shadow + '">' + LABEL + '</text>';
    s.staticSvg = st2; s.staticKey = staticKey;
  }

  // ---- dynamic part ----
  var out = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" style="font-family:' + FONT + ';opacity:' + OPACITY + '">' + s.staticSvg;
  if (typeof cur === 'number') {
    var cc = pos(cur);
    if (alpha > 0) {
      var cp = pos(peak);
      out += seg(cc - dir * ov, cp, FILL_COLOR, fw, 'butt', ' stroke-opacity="' + (alpha * 0.5).toFixed(2) + '"');
      out += marker(cp, PEAK_COLOR, ' stroke-opacity="' + alpha.toFixed(2) + '"');
    }
