    out += '<text x="' + nx.toFixed(2) + '" y="' + (VERTICAL ? a0 : ta + tw / 2 + ovh + mw / 2 + fs * 0.6).toFixed(2) + '" fill="' + TEXT_COLOR + '" font-size="' + fs.toFixed(1) + '" font-weight="bold" dominant-baseline="central" style="' + shadow + '">--</text>';
